ValidationRule.errorConditionFormula:
AND(
    ISPICKVAL(Status__c, "Closed"),
    $UserRole.Name <> "System Administrator",
    OR(
        /* 不是 CC 也不是 B2B */
        AND(
            NOT(CONTAINS($UserRole.Name, "CC")),
            NOT(CONTAINS($UserRole.Name, "B2B"))
        ),
        /* CC 沒填 CED_Note__c */
        AND(
            CONTAINS($UserRole.Name, "CC"),
            ISBLANK(CED_Note__c)
        ),
        /* B2B 沒填 PSP_Note__c */
        AND(
            CONTAINS($UserRole.Name, "B2B"),
            ISBLANK(PSP_Note__c)
        )
    )
)
